WITH exploded AS (SELECT id, host, log_ts, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, value), with_gaps AS (SELECT *, CASE WHEN LAG(log_ts) OVER (PARTITION BY host ORDER BY log_ts, id, k) IS NULL OR log_ts > LAG(log_ts) OVER (PARTITION BY host ORDER BY log_ts, id, k) + INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS new_group_flag FROM exploded), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY host ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), latest AS (SELECT * FROM islands QUALIFY ROW_NUMBER() OVER (PARTITION BY host ORDER BY latency_ms DESC NULLS LAST, id, k) = 1), latest_app_logs AS (SELECT id, status_code, k, value FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY host ORDER BY new_group_flag DESC NULLS FIRST, id, k) AS latest_rank FROM latest) t WHERE latest_rank = 1) SELECT id, status_code, k, value FROM latest_app_logs ORDER BY status_code DESC NULLS FIRST
